// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint128).max);
        Reverter attacker = new Reverter();
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        bool ok;
        vm.prank(address(attacker));
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Rule: a failed outgoing withdrawal call must revert the whole withdrawal.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
